package com.cryptoloan.contract.adapters.out.persistence;import com.cryptoloan.contract.domain.model.ContractProof;import com.cryptoloan.contract.domain.port.out.ContractPorts.Repository;import java.util.Optional;import org.springframework.stereotype.Component;@Component class ContractRepositoryAdapter implements Repository{private final SpringDataContractRepository repo;ContractRepositoryAdapter(SpringDataContractRepository repo){this.repo=repo;}public ContractProof save(ContractProof p){ContractJpaEntity e=new ContractJpaEntity();e.loanId=p.loanId();e.borrowerEmail=p.borrowerEmail();e.contractHashHex=p.contractHashHex();e.userTxHash=p.userTxHash();e.adminTxHash=p.adminTxHash();e.documentReference=p.documentReference();e.generatedAt=p.generatedAt();return domain(repo.save(e));}public Optional<ContractProof>find(Long id){return repo.findById(id).map(this::domain);}private ContractProof domain(ContractJpaEntity e){return new ContractProof(e.loanId,e.borrowerEmail,e.contractHashHex,e.userTxHash,e.adminTxHash,e.documentReference,e.generatedAt);}}

